export type Koffi = typeof import('koffi');

// koffi is an optional peer dependency. The native CLI ships it; the npm CLI
// doesn't install it, because its install script makes pnpm ask the user to
// approve a build.

/** Whether koffi is installed, so the security chip can be used. */
export function hasKoffi(): boolean {
  try {
    require.resolve('koffi');
    return true;
  } catch {
    return false;
  }
}

// Load koffi only when the chip is used.
export function loadKoffi(): Koffi {
  return require('koffi') as Koffi;
}
